 37	     * @dev Same as {xref-Clones-clone-address-}[clone], but with a `value` parameter to send native currency
 38	     * to the new contract.
 39	     *
 40	     * WARNING: This function does not check if `implementation` has code. A clone that points to an address
 41	     * without code cannot be initialized. Initialization calls may appear to be successful when, in reality, they
 42	     * have no effect and leave the clone uninitialized, allowing a third party to initialize it later.
 43	     *
 44	     * NOTE: Using a non-zero value at creation will require the contract using this function (e.g. a factory)
 45	     * to always have enough balance for new deployments. Consider exposing this function under a payable method.
 46	     */
 47	    function clone(address implementation, uint256 value) internal returns (address instance) {
 48	        if (address(this).balance < value) {
 49	            revert Errors.InsufficientBalance(address(this).balance, value);
 50	        }
 51	        assembly ("memory-safe") {
 52	            // Cleans the upper 96 bits of the `implementation` word, then packs the first 3 bytes
 53	            // of the `implementation` address with the bytecode before the address.
 54	            mstore(0x00, or(shr(232, shl(96, implementation)), 0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000))
 55	            // Packs the remaining 17 bytes of `implementation` with the bytecode after the address.
 56	            mstore(0x20, or(shl(120, implementation), 0x5af43d82803e903d91602b57fd5bf3))
 57	            instance := create(value, 0x09, 0x37)
 58	        }
 59	        if (instance == address(0)) {
 60	            revert Errors.FailedDeployment();
 61	        }
 62	    }
